603	  async catalogoClientes(restaurantId: number) {
604	    const { data: crRows, error: errCr } = await this.supabase.client
605	      .from('customer_restaurants')
606	      .select('customer_id')
607	      .eq('restaurant_id', restaurantId);
608	    if (errCr) throw errCr;
609	    const customerIds = (crRows ?? []).map((r: any) => r.customer_id);
610	
611	    const [{ data: clientes, error: errClientes }, { data: cacheGdoor, error: errCache }, { data: mapeamentos, error: errMapa }] = await Promise.all([
612	      customerIds.length
613	        ? this.supabase.client.from('customers').select('id, name, email, phone_e164, cpf_cnpj').in('id', customerIds).order('name')
614	        : Promise.resolve({ data: [], error: null }),
615	      this.supabase.client
616	        .from('gdoor_cliente_cache')
617	        .select('codigo, nome, cnpj_cnpf, telefone, email, bloqueado_sync')
618	        .eq('restaurant_id', restaurantId)
619	        .order('nome'),
620	      this.supabase.client
621	        .from('gdoor_cliente_mapeamento')
622	        .select('customer_id, codigo_gdoor')
623	        .eq('restaurant_id', restaurantId),
624	    ]);
625	    if (errClientes) throw errClientes;
626	    if (errCache) throw errCache;
627	    if (errMapa) throw errMapa;
628	
629	    const mapaPorCliente = Object.fromEntries((mapeamentos ?? []).map((m: any) => [m.customer_id, m]));
630	    const mapaPorCodigo = Object.fromEntries((mapeamentos ?? []).map((m: any) => [m.codigo_gdoor, m]));
631	    const cachePorCodigo = Object.fromEntries((cacheGdoor ?? []).map((e: any) => [e.codigo, e]));
632	
633	    const clientesDelivery = (clientes ?? []).map((c: any) => {
634	      const mapa = mapaPorCliente[c.id];
635	      const item = mapa ? cachePorCodigo[mapa.codigo_gdoor] : null;
636	      const diverge = !!item && (nomeDiverge(c.name, item.nome) || telefoneDiverge(c.phone_e164, item.telefone) || nomeDiverge(c.email, item.email));
637	      return { id: c.id, name: c.name, email: c.email, phone_e164: c.phone_e164, cpf_cnpj: c.cpf_cnpj, codigo_gdoor: mapa?.codigo_gdoor ?? null, diverge, sincronizavel: !!normalizarCnpj(c.cpf_cnpj) };
638	    });
639	
640	    const clientesGdoor = (cacheGdoor ?? []).map((e: any) => {
641	      const mapa = mapaPorCodigo[e.codigo];
642	      const cliente = mapa ? (clientes ?? []).find((c: any) => c.id === mapa.customer_id) : null;
643	      const diverge = !!cliente && (nomeDiverge(cliente.name, e.nome) || telefoneDiverge(cliente.phone_e164, e.telefone) || nomeDiverge(cliente.email, e.email));
644	      return { codigo: e.codigo, nome: e.nome, cnpj_cnpf: e.cnpj_cnpf, telefone: e.telefone, email: e.email, bloqueado_sync: e.bloqueado_sync, customer_id: mapa?.customer_id ?? null, nome_delivery: cliente?.name ?? null, diverge, sincronizavel: !!normalizarCnpj(e.cnpj_cnpf) };
645	    });
646	
647	    return { clientes_delivery: clientesDelivery, clientes_gdoor: clientesGdoor };
648	  }
