659	      .eq('restaurant_id', restaurantId)
660	      .in('codigo', codigos);
661	    if (errGdoor) throw errGdoor;
662	
663	    const { data: mapeamentos } = await this.supabase.client
664	      .from('gdoor_cliente_mapeamento')
665	      .select('codigo_gdoor')
666	      .eq('restaurant_id', restaurantId)
667	      .in('codigo_gdoor', codigos);
668	    const jaMapeados = new Set((mapeamentos ?? []).map((m: any) => m.codigo_gdoor));
669	
670	    const { data: candidatosCpf } = await this.supabase.client
671	      .from('customers')
672	      .select('id, cpf_cnpj')
673	      .not('cpf_cnpj', 'is', null);
674	
675	    const importados: string[] = [];
676	    const ignorados: { codigo: string; motivo: string }[] = [];
677	
678	    for (const item of clientesGdoor ?? []) {
679	      if (jaMapeados.has(item.codigo)) {
680	        ignorados.push({ codigo: item.codigo, motivo: 'já mapeado' });
681	        continue;
682	      }
683	      if (item.bloqueado_sync) {
