715	              cidade: item.cidade ?? '',
716	              estado: item.uf ?? '',
717	              cep: item.cep ?? '',
718	            },
719	            lat: item.lat ?? null,
720	            lng: item.lon ?? null,
721	          })
722	          .select('id')
723	          .single();
724	        if (errNovo) {
725	          ignorados.push({ codigo: item.codigo, motivo: 'falha ao criar cliente' });
726	          continue;
727	        }
728	        customerId = novo.id;
729	      }
730	
731	      await this.supabase.client
732	        .from('customer_restaurants')
733	        .upsert({ customer_id: customerId, restaurant_id: restaurantId }, { onConflict: 'customer_id,restaurant_id' });
734	
735	      await this.supabase.client.from('gdoor_cliente_mapeamento').upsert(
736	        { restaurant_id: restaurantId, customer_id: customerId, codigo_gdoor: item.codigo, atualizado_em: new Date().toISOString() },
737	        { onConflict: 'restaurant_id,customer_id' },
738	      );
