1	import { Injectable, NotFoundException } from '@nestjs/common';
2	import * as crypto from 'crypto';
3	import { SupabaseService } from '../supabase/supabase.service';
4	import { PlanosService } from '../planos/planos.service';
5	
6	const normalizarCnpj = (v: string | null | undefined) => (v ?? '').replace(/\D/g, '');
7	
8	// Só dígitos, últimos 11 (DDD + número) — descarta prefixo de país/zero à
9	// esquerda (+5591999998888 e 91999998888 têm que bater). CPF/CNPJ é usado
10	// primeiro por ser mais forte, mas raramente preenchido no checkout do
11	// delivery — telefone é o dado que realmente costuma existir nos dois lados.
12	const normalizarTelefone = (v: string | null | undefined) => {
13	  const digitos = (v ?? '').replace(/\D/g, '');
14	  return digitos.length >= 8 ? digitos.slice(-11) : '';
15	};
16	
17	const CATEGORIA_PADRAO_IMPORTACAO = 'Importado do GDOOR';
18	
19	// Tolerância de 1 centavo pra não marcar como "divergente" arredondamento de ponto flutuante.
20	const precoDiverge = (a: number | null, b: number | null) => {
21	  if (a == null || b == null) return false;
22	  return Math.abs(a - b) > 0.01;
23	};
24	const qtdDiverge = (a: number | null, b: number | null) => {
25	  if (a == null || b == null) return false;
26	  return Math.abs(a - b) > 0.001;
27	};
28	const nomeDiverge = (a: string | null, b: string | null) => {
29	  if (!a || !b) return false;
30	  return a.trim().toLowerCase() !== b.trim().toLowerCase();
31	};
32	// Compara telefone normalizado — formatos diferentes (+55 na frente, DDD com
33	// ou sem 9º dígito) não devem contar como divergência.
34	const telefoneDiverge = (a: string | null, b: string | null) => {
35	  const na = normalizarTelefone(a);
36	  const nb = normalizarTelefone(b);
37	  if (!na || !nb) return false;
38	  return na !== nb;
39	};
40	
41	@Injectable()
42	export class GdoorService {
43	  constructor(private supabase: SupabaseService, private planos: PlanosService) {}
44	
45	  // ── Lado dono (RestaurantOwnerGuard) ──────────────────────────────
46	
47	  async gerarToken(restaurantId: number) {
48	    const token = crypto.randomUUID();
49	    const { error } = await this.supabase.client
50	      .from('restaurants')
51	      .update({ gdoor_agente_token: token })
52	      .eq('id', restaurantId);
53	    if (error) throw error;
54	    return { token };
55	  }
56	
57	  async statusAgente(restaurantId: number) {
58	    const { data } = await this.supabase.client
59	      .from('restaurants')
60	      .select('gdoor_agente_token, gdoor_agente_ultimo_ping, gdoor_cnpj_esperado, gdoor_cnpj_confirmado')
61	      .eq('id', restaurantId)
62	      .maybeSingle();
63	
64	    const ultimoPing = data?.gdoor_agente_ultimo_ping ? new Date(data.gdoor_agente_ultimo_ping) : null;
65	    const online = !!ultimoPing && Date.now() - ultimoPing.getTime() < 60_000;
66	    const cnpjEsperado = data?.gdoor_cnpj_esperado ?? null;
67	    const cnpjConfirmado = data?.gdoor_cnpj_confirmado ?? null;
68	    // Sem CNPJ esperado cadastrado ainda = não dá pra afirmar que confere nem que não confere.
69	    const cnpjConfere = cnpjEsperado && cnpjConfirmado
70	      ? normalizarCnpj(cnpjEsperado) === normalizarCnpj(cnpjConfirmado)
71	      : null;
72	
73	    return {
74	      pareado: !!data?.gdoor_agente_token,
75	      online,
76	      ultimo_ping: data?.gdoor_agente_ultimo_ping ?? null,
77	      cnpj_esperado: cnpjEsperado,
78	      cnpj_confirmado: cnpjConfirmado,
79	      cnpj_confere: cnpjConfere,
80	    };
81	  }
82	
83	  async salvarCnpjEsperado(restaurantId: number, cnpj: string) {
84	    const { error } = await this.supabase.client
85	      .from('restaurants')
86	      .update({ gdoor_cnpj_esperado: cnpj?.trim() || null })
87	      .eq('id', restaurantId);
88	    if (error) throw error;
89	    return { ok: true };
90	  }
91	
92	  // ── Lado agente (AgenteGdoorGuard) ────────────────────────────────
93	
94	  // Chamado pelo agente Python a cada poll — mantém gdoor_cnpj_confirmado sempre
95	  // atualizado com o que o Firebird local reportou de verdade, pra comparação.
96	  async registrarCnpjAgente(restaurantId: number, cnpj: string) {
97	    if (!cnpj?.trim()) return { ok: true };
98	    const { error } = await this.supabase.client
99	      .from('restaurants')
100	      .update({ gdoor_cnpj_confirmado: cnpj.trim() })
101	      .eq('id', restaurantId);
102	    if (error) throw error;
103	    return { ok: true };
104	  }
105	
106	  // INSERT puro — nunca faz chamada HTTP. O agente é quem puxa (polling), nunca
107	  // o contrário (server_delivery roda na nuvem, não alcança a máquina do restaurante).
108	  // Resolve product_id -> codigo_gdoor aqui (mapeamento cadastrado no painel) e já
109	  // grava no payload, pra o agente não precisar de nenhum mapeamento local — só
110	  // grava o que o job mandar. Item sem mapeamento vai com codigo_gdoor: null, e o
111	  // agente reporta erro pedindo pra mapear (visível no painel).
112	  async criarJob(restaurantId: number, pedidoId: number, cliente: any, itens: any[]) {
113	    // Módulo é comprável no pacote (igual Delivery/Salão) — se a loja não tem,
114	    // não enfileira. Chamadores (pedidos.service.ts, salao.service.ts) tratam
115	    // isso como best-effort (.catch(() => {})), então um no-op silencioso aqui
116	    // é o ponto único de enforcement pros dois gatilhos (delivery e comanda).
117	    const { data: restaurante } = await this.supabase.client
118	      .from('restaurants')
119	      .select('modulo_gdoor')
120	      .eq('id', restaurantId)
121	      .maybeSingle();
122	    if (!restaurante?.modulo_gdoor) return { ok: false, motivo: 'modulo_gdoor_desabilitado' };
123	
124	    const productIds = [...new Set(itens.map((i: any) => i.product_id))];
125	    const { data: mapeamentos } = await this.supabase.client
126	      .from('gdoor_produto_mapeamento')
127	      .select('product_id, codigo_gdoor')
128	      .eq('restaurant_id', restaurantId)
129	      .in('product_id', productIds.length ? productIds : [0]);
130	    const mapa = Object.fromEntries((mapeamentos ?? []).map((m: any) => [m.product_id, m.codigo_gdoor]));
131	
132	    const itensComCodigo = itens.map((i: any) => ({ ...i, codigo_gdoor: mapa[i.product_id] ?? null }));
133	
134	    // Se o cliente do pedido já tiver um cadastro mapeado no GDOOR (sincronização
135	    // de clientes por CPF/CNPJ), usa o código dele em vez do genérico
136	    // "Consumidor" — o agente decide o fallback se isso vier vazio.
137	    let clienteCodigoGdoor: string | null = null;
138	    if (cliente?.id) {
139	      const { data: mapaCliente } = await this.supabase.client
140	        .from('gdoor_cliente_mapeamento')
141	        .select('codigo_gdoor')
142	        .eq('restaurant_id', restaurantId)
143	        .eq('customer_id', cliente.id)
144	        .maybeSingle();
145	      clienteCodigoGdoor = mapaCliente?.codigo_gdoor ?? null;
146	    }
147	    const clienteComCodigo = { ...cliente, codigo_gdoor: clienteCodigoGdoor };
148	
149	    const { error } = await this.supabase.client
150	      .from('gdoor_jobs')
151	      .insert({ restaurant_id: restaurantId, pedido_id: pedidoId, payload: { cliente: clienteComCodigo, itens: itensComCodigo } });
152	    if (error) throw error;
153	    return { ok: true };
154	  }
155	
156	  // ── Catálogo/mapeamento de produtos (lado dono lê e edita, agente só escreve o cache) ──
157	
