async comandasAbertas(restaurantId: number) {
  // `total` sozinho é só a soma bruta dos produtos — desconto/acréscimo ficam em
  // colunas separadas e só se somam a ele no pagamento (ver `pagar()`). Manda os
  // dois aqui pro frontend calcular o valor real da comanda ainda aberta, senão
  // o card mostra um total que não bate com o que vai ser cobrado de verdade.
  const { data, error } = await this.supabase.client
    .from('orders')
    .select('id, mesa_id, cliente_mesa_nome, cliente_mesa_telefone, total, desconto_valor, acrescimo_valor, status, payment_method, numero_comanda, created_at, mesas(numero, nome), garcons(nome), aberto_por_nome')

